class NonceReuseError(Exception):
    """Raised when a 96-bit nonce has already been registered and is reused."""
    pass


class NonceShieldV2:
    """Tracks used 96-bit nonces to prevent replay attacks and nonce reuse."""

    def __init__(self):
        # Using a set to store seen 96-bit nonces (typically represented as int, bytes, or hex str)
        self._used_nonces = set()

    def register(self, nonce) -> None:
        """Register a 96-bit nonce.

        Raises:
            NonceReuseError: If the nonce has already been registered.
            ValueError: If the nonce is invalid or not 96 bits.
        """
        # Validate nonce size if provided as bytes (96 bits = 12 bytes) or int (< 2^96)
        if isinstance(nonce, bytes):
            if len(nonce) != 12:
                raise ValueError("Nonce must be exactly 96 bits (12 bytes).")
        elif isinstance(nonce, int):
            if not (0 <= nonce < (1 << 96)):
                raise ValueError("Nonce integer must fit within 96 bits.")
        elif isinstance(nonce, str):
            # If hex string is passed, check length (12 bytes = 24 hex characters)
            try:
                decoded = bytes.fromhex(nonce)
                if len(decoded) != 12:
                    raise ValueError("Nonce hex string must represent 12 bytes (96 bits).")
            except ValueError as e:
                if "Nonce hex string" in str(e):
                    raise
                raise ValueError("Invalid hex string for nonce.") from e
        else:
            raise TypeError("Nonce must be of type bytes, int, or str (hex).")

        # Normalize representation for storage if desired, or keep as-is.
        # Storing the normalized form or original form consistently.
        if isinstance(nonce, str):
            canonical_nonce = bytes.fromhex(nonce)
        elif isinstance(nonce, int):
            canonical_nonce = nonce.to_bytes(12, byteorder='big')
        else:
            canonical_nonce = nonce

        if canonical_nonce in self._used_nonces:
            raise NonceReuseError(f"Nonce reuse detected: {nonce}")

        self._used_nonces.add(canonical_nonce)

    def is_used(self, nonce) -> bool:
        """Check if a 96-bit nonce has already been registered without raising an error."""
        try:
            if isinstance(nonce, str):
                canonical_nonce = bytes.fromhex(nonce)
            elif isinstance(nonce, int):
                canonical_nonce = nonce.to_bytes(12, byteorder='big')
            else:
                canonical_nonce = nonce
        except Exception:
            return False

        return canonical_nonce in self._used_nonces
